SELECT c.seller_name AS sellerName, c.marketplace AS marketplace, COUNT(*) AS hitCount, ROUND(AVG(c.price), 2) AS avgPrice, ( SELECT SUBSTRING_INDEX(c2.node_label_path, ':', -1) FROM competitor_products_clean c2 WHERE c2.marketplace = c.marketplace AND c2.seller_name = c.seller_name AND c2.m01_active = 1 AND c2.node_label_path IS NOT NULL AND c2.node_label_path != '' GROUP BY SUBSTRING_INDEX(c2.node_label_path, ':', -1) ORDER BY COUNT(*) DESC LIMIT 1 ) AS topCategory FROM competitor_products_clean c WHERE c.m01_active = 1
AND c.marketplace = #{marketplace}
AND c.seller_name IS NOT NULL AND c.seller_name != '' GROUP BY c.seller_name, c.marketplace HAVING COUNT(*) >= #{minCount} ORDER BY hitCount DESC, avgPrice ASC LIMIT #{limit}

mapper.update:
UPDATE competitor_products cp
SET cp.m01_active =
    CASE
        WHEN cp.available_date IS NOT NULL
         AND cp.available_date > 0
         AND cp.price IS NOT NULL
         AND cp.price >= #{priceMin}
         AND cp.price <= #{priceMax}
         AND cp.weight_g IS NOT NULL
         AND cp.weight_g < #{weightMax}
         AND DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) < #{listingDaysMax}
         AND (
            (
                cp.units IS NOT NULL
                AND (
                    (DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) <= 30 AND cp.units >= #{sales30})
                    OR (DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) <= 60 AND cp.units >= #{sales60})
                    OR (DATEDIFF(NOW(), FROM_UNIXTIME(cp.available_date / 1000)) <= 90 AND cp.units >= #{sales90})
                )
            )

            OR (cp.bsr IS NOT NULL AND cp.bsr > 0 AND cp.bsr < #{bsrMax})

         )
        THEN 1
        ELSE 0
    END
WHERE cp.marketplace = #{marketplace}

UPDATE competitor_products
SET m01_active = 0
WHERE marketplace = #{marketplace}
  AND m01_active = 1
  AND (
      available_date IS NULL OR available_date <= 0
      OR DATEDIFF(NOW(), FROM_UNIXTIME(available_date / 1000)) >= #{listingDaysMax}
  )

UPDATE competitor_products_clean
SET m01_active = 0
WHERE marketplace = #{marketplace}
  AND m01_active = 1
  AND (
      available_date IS NULL OR available_date <= 0
      OR DATEDIFF(NOW(), FROM_UNIXTIME(available_date / 1000)) >= #{listingDaysMax}
  )
